INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63276271', 63276271, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA RUMAH SUSUN VIII', 'Belanja Jasa Konsultansi Konstruksi Perencanaan Pemeliharaan Berkala Sarana dan Prasarana Rumah Susun (Cipinang Besar Selatan)', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 486588032, 'February 2026', 'APBD', 1, 1, '1 paket', 'Belanja Jasa Konsultansi Konstruksi Perencanaan Pemeliharaan Berkala Sarana dan Prasarana Rumah Susun (Cipinang Besar Selatan)', 'Ruang Lingkup Pekerjaaan (Belanja Jasa Konsultansi Konstruksi Perencanaan Pemeliharaan Berkala Sarana dan Prasarana Rumah Susun (Cipinang Besar Selatan)) 1. Tahap Konsepsi Perancangan, meliputi : a) Mengumpulkan serta mengolah data dan informasi kerusakan di lapangan, b) Menyusun program kerja yang akan digunakan sebagai dasar perencanaan atau perancangan teknis yang didasarkan pada Kerangka Acuan Kerja (KAK), c) Berkonsultasi dan melakukan asistensi dengan Unit Pengelola Rumah Susun VIII dan Bidang Perumahan Dinas Perumahan Rakyat dan Kawasan Permukiman sesuai tupoksi. 2) Tahap Pra Rancangan, meliputi: a) Membuat gambar existing dan gambar rencana perbaikan, meliputi: denah, tampak, potongan, dan detail, b) Membuat perkiraan rencana anggaran biaya, termasuk survey harga material dan upah. c) Berkonsultasi dan melakukan asistensi dengan Unit Pengelola Rumah Susun VIII dan Bidang Perumahan Dinas Perumahan Rakyat dan Kawasan Permukiman sesuai tupoksi. 3) Tahap Pengembangan Rancangan, meliputi : a) Membantu konsepsi perencanaan atau perancangan teknis secara keseluruhan ditinjau dari keselarasan sistem perbaikan gedung yang terkandung di dalamnya, b) Membuat penjelasan secara garis besar bahan-bahan yang akan digunakan pada kegiatan pemeliharaan, c) Membuat perkiraan biaya (RAB) d) Berkonsultasi dan melakukan asistensi dengan Unit Pengelola Rumah Susun VIII dan Bidang Perumahan Dinas Perumahan Rakyat dan Kawasan Permukiman sesuai tupoksi. 4) Tahap Rancangan Detail, meliputi : a) Membuat uraian detail mengenai rencana perbaikan arsitektur, rencana perbaikan mekanikal, elektrikal, rencana perbaikan utilitas gedung, lengkap dengan perhitungan-perhitungannya, b) Membuat dokumen persyaratan administrasi, persyaratan umum, dokumen spesifikasi teknis, rencana jadwal pekerjaan fisik perawatan, Metode Pelaksanaan yang diterapkan pada setiap pekerjaan, Kurva S pelaksanaan kegiatan (berdasarkan bobot biaya dan waktu). c) Membuat gambar detail (DED) dan penyusunan Rencana Kerja dan Syarat (RKS), serta Rencana Anggaran Biaya (RAB). d) Menyusun RAB e-katalog menyesuaikan dengan pekerjaan yang ada dalam e-katalog DKI Jakarta. e) Berkonsultasi dan melakukan asistensi dengan Unit Pengelola Rumah Susun VIII dan Bidang Perumahan Dinas Perumahan Rakyat dan Kawasan Permukiman sesuai tupoksi. 5) Tahap Tender Penyedia Jasa Pelaksana Konstruksi, meliputi : a) Menyusun dokumen persiapan pengadaan pekerjaan fisik perawatan berkala (RAB, KAK/TOR, Spesifikasi Teknis, RKS, Gambar DED, Rencana Kurva S, Rencana Jadwal Pelaksanaan Pekerjaan); b) Memberikan penjelasan mengenai pekerjaan yang akan ditenderkan pada rapat penjelasan (aanwijzing), c) Membantu panitia pengadaan barang/jasa dalam melakukan evaluasi penawaran, d) Melaksanakan tugas-tugas yang sama apabila terjadi pemilihan penyedia barang/jasa ulang, 6) Tahap pengawasan berkala, sekurang-kurangnya sekali untuk setiap minggu, meliputi : a) Memeriksa pelaksaan pekerjaan di lapangan sesuai dengan keluaran yang dituangkan dalam angka, b) Melakukan kontrol terhadap pekerjaan yang dilaksanakan oleh kontraktor pelaksana perawatan berkala dan menilai kinerja dari konsultan pengawas selama masa pekerjaan perawatan berkala rumah susun, c) Memberikan penjelasan terhadap permasalahan yang timbul selama masa pelaksaan, d) Menyusun laporan pelaksanaan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 854255);
