INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63326446', 63326446, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Sewa Kendaraan Roda 4', 'Barang', 'E-Purchasing', 'Aceh, Pidie Jaya (Kab.)', 144000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'Pekerjaan ini merupakan jasa sewa kendaraan roda empat tanpa pengemudi yang digunakan untuk menunjang kegiatan kedinasan, operasional lapangan, pelayanan pertanahan, pengukuran, survei, monitoring, dan kegiatan administrasi Kantor Pertanahan Kabupaten Pidie Jaya. Penyedia bertanggung jawab atas ketersediaan kendaraan dalam kondisi laik jalan, aman, dan siap pakai selama masa kontrak, termasuk pemeliharaan rutin dan perbaikan apabila terjadi kerusakan bukan akibat kelalaian pengguna.', 'Spesifikasi teknis kendaraan yang disewa meliputi: A. Spesifikasi Umum Kendaraan • Jenis kendaraan: Mobil penumpang roda 4 • Kapasitas: Minimal 7 (Tujuh) orang • Tipe kendaraan: MPV / SUV • Tahun kendaraan: Minimal tahun ≤ 1 tahun terakhir • Kondisi kendaraan: Baik, layak jalan, dan terawat B. Spesifikasi Teknis • Mesin dalam kondisi normal dan prima • Transmisi: Manual atau otomatis • Sistem rem, lampu, dan kelistrikan berfungsi dengan baik • AC berfungsi dengan baik • Ban dalam kondisi layak pakai (termasuk ban cadangan) • Dilengkapi sabuk pengaman (safety belt) C. Legalitas dan Administrasi • STNK kendaraan aktif dan sah • Pajak kendaraan hidup • Kendaraan diasuransikan (jika disyaratkan) • Plat nomor sesuai ketentuan peraturan perundang-undangan D. Ketentuan Layanan • Perawatan rutin dan perbaikan kendaraan menjadi tanggung jawab penyedia • Kendaraan pengganti disediakan apabila kendaraan utama mengalami kerusakan • BBM ditanggung pengguna (kecuali ditentukan lain) • Penggunaan kendaraan untuk keperluan dinas Kantor Pertanahan Kabupaten Pidie Jaya', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 856426);
