INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63305620', 63305620, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR KEKARANTINAAN KESEHATAN TANJUNG PRIOK', 'Manekin CPR Half Body', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Utara (Kota)', 19920000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '3 Unit', 'Pengadaan Bahan/Alat Bahan Medis dan Non Medis Untuk Pelayanan dan Advokasi Kesehatan (Manekin CPR Half Body)', 'Spesifikasi : Simulasi Saluran Napas: Memungkinkan pembukaan saluran napas standar (mendongakkan kepala/mengangkat dagu). Pernapasan Buatan (Bantuan Napas): Instruktur dapat melatih pemberian napas buatan, dan beberapa model mungkin menunjukkan kenaikan dada yang terlihat jika dilakukan dengan benar. Kompresi Dada Eksternal: Kedalaman Kompresi: Dirancang untuk memungkinkan kompresi dengan kedalaman yang benar (umumnya 5-6 cm untuk dewasa). Umpan Balik (Feedback): Banyak manikin modern, termasuk merek yang dijual di Indonesia seperti Prestan atau Nesco, dilengkapi dengan mekanisme umpan balik visual atau auditori (klik) untuk menunjukkan kompresi yang benar atau berlebihan. Fitur Anatomi Realistis: Karakteristik anatomi yang jelas, perasaan sentuhan yang realistis, dan warna kulit yang hidup. Portabilitas: Karena hanya half body, manikin ini lebih ringkas dan mudah dibawa untuk pelatihan di berbagai lokasi. Bahan: terbuat dari bahan PVC atau silikon yang tahan lama.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 856868);
