INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63326449', 63326449, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Sewa Kendaraan Roda 2', 'Barang', 'E-Purchasing', 'Aceh, Pidie Jaya (Kab.)', 24000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '2 Unit x 12 Bulan = 24 Bulan', 'Pekerjaan ini merupakan jasa sewa kendaraan roda dua yang digunakan untuk menunjang kegiatan operasional kedinasan, terutama untuk mobilitas pegawai dalam kegiatan lapangan seperti pengumpulan data yuridis, pengukuran, pemetaan, survei lokasi, monitoring, dan pelayanan pertanahan di wilayah Kabupaten Pidie Jaya. Penyedia wajib menyediakan kendaraan dalam kondisi baik, aman, dan siap pakai selama masa sewa, serta bertanggung jawab atas pemeliharaan dan perbaikan kendaraan apabila terjadi kerusakan bukan akibat kelalaian pengguna.', 'Spesifikasi Pekerjaan A. Spesifikasi Umum Kendaraan Jenis kendaraan : Sepeda motor roda dua Kapasitas mesin : Minimal 110 cc Sistem bahan bakar : Injeksi Tahun kendaraan : Minimal tahun ≤ 1 tahun terakhir) Kondisi kendaraan : Baik, layak jalan, dan terawat B. Spesifikasi Teknis Mesin dalam kondisi normal dan prima Sistem pengereman berfungsi baik (rem depan dan belakang) Lampu utama, lampu sein, dan klakson berfungsi Ban depan dan belakang layak pakai Suspensi berfungsi dengan baik Starter elektrik dan/atau kick starter berfungsi C. Legalitas dan Administrasi STNK kendaraan aktif dan sah Pajak kendaraan hidup Plat nomor resmi sesuai ketentuan Kendaraan diasuransikan (jika dipersyaratkan) D. Ketentuan Layanan Perawatan rutin dan perbaikan kendaraan menjadi tanggung jawab penyedia Kendaraan pengganti disediakan jika kendaraan rusak dan tidak dapat digunakan BBM menjadi tanggung jawab pengguna (kecuali ditentukan lain) Kendaraan digunakan khusus untuk keperluan dinas Kantor Pertanahan Kabupaten Pidie Jaya', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 858401);
