INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63326448', 63326448, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'PEMELIHARAAN BANGUNAN GEDUNG DAN HALAMAN KANTOR', 'Barang', 'E-Purchasing', 'Aceh, Pidie Jaya (Kab.)', 52660000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pekerjaan pemeliharaan bangunan gedung dan halaman kantor dilaksanakan untuk menjaga kondisi fisik bangunan dan lingkungan kantor agar tetap layak fungsi, aman, bersih, dan nyaman dalam mendukung pelaksanaan tugas dan pelayanan perkantoran. Ruang lingkup pekerjaan meliputi pemeliharaan ringan dan rutin, antara lain: a. Perbaikan minor pada bangunan gedung kantor. b. Pemeliharaan instalasi bangunan (listrik, air, sanitasi). c. Pemeliharaan kebersihan dan kerapian halaman kantor. d. Penataan dan perawatan fasilitas pendukung kantor.', '1. Pemeliharaan Bangunan Gedung a. Perbaikan ringan dinding, lantai, plafon, pintu, dan jendela. b. Perawatan atap, talang air, dan saluran pembuangan. c. Pemeliharaan instalasi listrik dan air bersih. d. Perbaikan fasilitas sanitasi (toilet, wastafel). 2. Pemeliharaan Halaman Kantor a. Pembersihan dan perawatan halaman. b. Pemangkasan rumput dan tanaman. c. Perawatan saluran drainase lingkungan. d. Penataan area parkir dan akses masuk kantor. 3. Standar Pelaksanaan a. Dilaksanakan sesuai ketentuan teknis bangunan gedung dan K3. b. Menggunakan material yang layak dan sesuai standar. c. Tidak mengganggu aktivitas pelayanan kantor. 4. Hasil Pekerjaan a. Bangunan dan halaman kantor dalam kondisi terawat, bersih, dan berfungsi dengan baik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 858414);
