INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63327031', 63327031, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Belanja Sewa Mesin Fotocopy 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 120000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. sewa mesin fotocopy ( 2, UT, @ 60000000 ); Ruang lingkup Pengadaan Sewa Mesin Fotocopy, meliputi sebagai berikut: 1. Penyedia wajib menyediakan 2 unit mesin fotokopi sesuai spesifikasi teknis. 2. Melakukan pengiriman, instalasi, dan uji coba di lokasi pengguna. 3. Menyediakan bahan habis pakai (toner, drum, developer, dll) kecuali kertas. 4. Memberikan layanan pemeliharaan berkala dan perbaikan bila terjadi kerusakan. 5. Menyediakan unit pengganti jika mesin rusak dan tidak dapat diperbaiki dalam waktu maksimal 1x24 jam. 6. Memberikan pelatihan singkat kepada pengguna mengenai cara pengoperasian mesin.', 'Spesifikasi Utama Tipe Multifunction Printer (Print, Copy, Scan, Optional Fax) Teknologi: Laser warna (Color Laser MFP) ecepatan Cetak & Copy Hingga 45 halaman per menit (ppm) (A4, warna & hitam putih) Resolusi Print: Hingga 1200 x 2400 dpi Copy: Hingga 600 x 600 dpi Ukuran Kertas Standar: A5 – A3 Bypass tray mendukung kertas tebal, amplop, dan ukuran custom Berat kertas: ±60 – 300 gsm (tergantung tray) Kapasitas Kertas Standar tray: ±1.140 lembar Maksimal (dengan tambahan tray): Hingga ±5.140 lembar Fitur Otomatis Automatic Duplex (bolak-balik otomatis) DADF (Duplex Automatic Document Feeder) Scan Scan to Email Scan to Folder (SMB/FTP) Scan ke USB Format: PDF, JPEG, TIFF, dll. Kecepatan scan bisa > 100 ipm (duplex) Konektivitas Ethernet USB Wi-Fi (opsional) Mendukung Apple AirPrint & Mopria Layar Touchscreen warna ±10 inci Interface seperti tablet (Xerox ConnectKey) Keamanan User authentication Data encryption Secure print Hard disk overwrite', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 859899);
